	JoinThreshold      int                  `bson:"join_threshold"       json:"join_threshold"`
	JoinWindowMs       int                  `bson:"join_window_ms"       json:"join_window_ms"`
	Action             ModerationRaidAction `bson:"action"               json:"action"`
