package validations

import (
	"kena.bot/api-db-go/internal/domain/dbguild"
)

// ModuleParams matches `paramsModuleValidation` (bot_id + guild_id).
// Used by every music/greeter/logs handler.
type ModuleParams struct {
	BotID   string `params:"bot_id"   validate:"required"`
	GuildID string `params:"guild_id" validate:"required"`
}

// ModuleMusicFieldParams adds the `:field` path segment. The field is
// constrained to the keys of `dbguild.ModuleMusic` at runtime by the
// handler — go-playground/validator cannot enforce "must be a key of this
// struct" without a custom tag, so the handler does the membership check
// after parsing.
type ModuleMusicFieldParams struct {
	BotID   string `params:"bot_id"   validate:"required"`
	GuildID string `params:"guild_id" validate:"required"`
	Field   string `params:"field"    validate:"required"`
}

// ModuleEnabledQuery matches `queryModuleEnabledValidation` in the
// Node service. `Module` is optional and, when present, must be one of
// the canonical module keys (`music | greeter | logs`). The
// go-playground `oneof` tag enforces the enum at bind time — unknown
// values produce a 400 Zod-shaped error.
//
// `tickets` is intentionally excluded from the `oneof` enum: the Node
// ModulesKeys array includes it, but the Node validator rejects it on
// the query param, and the controller has no implementation. The Go
// port mirrors that.
type ModuleEnabledQuery struct {
	Module string `query:"module" validate:"omitempty,oneof=music greeter logs"`
}

// UpdateModuleMusicBody mirrors the Node `updateModuleMusicSchema` (which
// is `moduleMusicSchema.partial()`). All fields are pointers so the
// handler can distinguish "absent" from "zero value". Only non-nil fields
// are forwarded into the Mongo `$set` payload.
//
// PER OLA-3 DECISION: all module PATCH bodies use `.strict()` semantics —
// unknown keys are rejected. The Node music body is the only one that
// silently drops them at the Mongoose layer; we tighten this to parity
// with greeter/logs (already `.strict()`).
type UpdateModuleMusicBody struct {
	SchemaVersion      *int                             `json:"schema_version,omitempty"`
	Enabled            *bool                            `json:"enabled,omitempty"`
	MaxSongDuration    *int                             `json:"max_song_duration,omitempty"`
	Loop               *dbguild.MusicLoop               `json:"loop,omitempty"`
	Volume             *int                             `json:"volume,omitempty"`
	RadioMode          *dbguild.RadioMode               `json:"radio_mode,omitempty"`
	MessageRetention   *bool                            `json:"message_retention,omitempty"`
	PinnedNowPlaying   *bool                            `json:"pinned_now_playing,omitempty"`
	VoiceStatusEnabled *bool                            `json:"voice_status_enabled,omitempty"`
	BotPoolEnabled     *bool                            `json:"bot_pool_enabled,omitempty"`
	EnhancedSearch     *bool                            `json:"enhanced_search,omitempty"`
	AutoDeleteCommands *[]string                        `json:"auto_delete_commands,omitempty"`
	AudioQuality       *dbguild.MusicAudioQuality       `json:"audio_quality,omitempty" validate:"omitempty,oneof=default hifi"`
	CommandsGlobal     *dbguild.MusicCommandAccess      `json:"commands_global,omitempty"`
	Commands           *map[string]dbguild.MusicCommand `json:"commands,omitempty"`
	TextChannels       *dbguild.ChannelsConfig          `json:"text_channels,omitempty"`
	VoiceChannels      *dbguild.ChannelsConfig          `json:"voice_channels,omitempty"`
	DJ                 *dbguild.DJ                      `json:"dj,omitempty"`
	RecommendedArtists *[]string                        `json:"recommended_artists,omitempty"`
}

// Set returns the BSON document for the `$set` payload. Returns nil when
// no fields were supplied so the repository can short-circuit and avoid
// issuing a no-op update.
func (b UpdateModuleMusicBody) Set() map[string]any {
	out := map[string]any{}
	if b.SchemaVersion != nil {
		out["schema_version"] = *b.SchemaVersion
	}
	if b.Enabled != nil {
		out["enabled"] = *b.Enabled
	}
	if b.MaxSongDuration != nil {
		out["max_song_duration"] = *b.MaxSongDuration
	}
	if b.Loop != nil {
		out["loop"] = string(*b.Loop)
	}
	if b.Volume != nil {
		out["volume"] = *b.Volume
	}
	if b.RadioMode != nil {
		out["radio_mode"] = *b.RadioMode
	}
	if b.MessageRetention != nil {
		out["message_retention"] = *b.MessageRetention
	}
	if b.PinnedNowPlaying != nil {
		out["pinned_now_playing"] = *b.PinnedNowPlaying
	}
	if b.VoiceStatusEnabled != nil {
		out["voice_status_enabled"] = *b.VoiceStatusEnabled
	}
	if b.BotPoolEnabled != nil {
		out["bot_pool_enabled"] = *b.BotPoolEnabled
	}
	if b.EnhancedSearch != nil {
		out["enhanced_search"] = *b.EnhancedSearch
	}
	if b.AutoDeleteCommands != nil {
		// Puntero + slice no vacío garantizado: el puntero distingue "no viene
		// en el PATCH" de "viene la lista vacía", que es un ajuste legítimo
		// ("no limpiar nada") y tiene que poder guardarse.
		list := *b.AutoDeleteCommands
		if list == nil {
			list = []string{}
		}
		out["auto_delete_commands"] = list
	}
	if b.AudioQuality != nil {
		out["audio_quality"] = string(*b.AudioQuality)
	}
	if b.CommandsGlobal != nil {
		out["commands_global"] = *b.CommandsGlobal
	}
	if b.Commands != nil {
		out["commands"] = *b.Commands
	}
	if b.TextChannels != nil {
		out["text_channels"] = *b.TextChannels
	}
	if b.VoiceChannels != nil {
		out["voice_channels"] = *b.VoiceChannels
	}
	if b.DJ != nil {
		out["dj"] = *b.DJ
	}
	if b.RecommendedArtists != nil {
		out["recommended_artists"] = *b.RecommendedArtists
	}
	if len(out) == 0 {
		return nil
	}
	return out
}

// RadioModeEnabled is a helper for the controller's PATCH side-effect
// (`redisAdapter.cache.lavalink.setPlayerPersistent`). Returns nil when the
// PATCH body omits `radio_mode` entirely; otherwise a pointer to the new value.
//
// `radio_mode` is whole-object REPLACE, not merge: its fields are values, not
// pointers, so a body carrying `radio_mode` ALWAYS sets `enabled` - omitting
// the field inside it means `false`. That is not a quirk of this helper: `Set`
// above writes that same `false` to Mongo, so the two destinations stay in
// step. The shared TS type (`library-shared/src/db/schemas/DBGuildSchemas.ts`)
// declares both fields required, so no typed client can send the partial.
func (b UpdateModuleMusicBody) RadioModeEnabled() *bool {
	if b.RadioMode == nil {
		return nil
	}
	v := b.RadioMode.Enabled
	return &v
}

package handlers

import (
	"bytes"
	"encoding/json"
	"strconv"

	"github.com/gofiber/fiber/v3"

	"kena.bot/api-db-go/internal/domain/dbguild"
	apierrors "kena.bot/api-db-go/internal/domain/errors"
	"kena.bot/api-db-go/internal/domain/validations"
	"kena.bot/api-db-go/internal/infrastructure/mongorepo"
	"kena.bot/api-db-go/internal/shared/result"
)

// sourceDetailModerationDBNotFound is the source detail stamped on the PATCH
// not-found envelope (the repo returns a bare nil there, so the handler has no
// Sourced to read it from). Kept in step with
// `mongo.SourceDetailModuleModerationDB` — the handler can't import the mongo
// infra package without a layering violation, so the string is duplicated
// locally, à la `sourceDetailGiveawayDBNotFound` in module_giveaway_handler.go.
const sourceDetailModerationDBNotFound = "mongo.guild.module_moderation"

// ModuleModerationHandler wires the two moderation endpoints behind a single
// struct.
//
// Mirrors `module-moderation-controller.ts` (the guild-scoped GET/PATCH).
//
// The result payload is `*dbguild.ModuleModeration` (pointer) so the not-found
// paths can emit `"data":null` — matching the Node controller, whose GET / PATCH
// not-found branches run `applySourceAndStash(sourced{data:null})` before
// throwing MODULE_NOT_FOUND (same as modmail/tempvoice/giveaway, tighter than the
// greeter/logs/music value-payload handlers).
//
// DELIBERATE DIVERGENCE from the Node controller (consistent with the
// greeter/modmail/tempvoice/giveaway mold, which also skips the guild pre-check):
//   - No `GuildRepository.checkGuildExists` → GUILD_NOT_FOUND pre-check on PATCH.
//     A missing guild makes the repo return nil, which the handler maps to
//     MODULE_NOT_FOUND (data:null) — the same not-found signal the update-null
//     branch produces, not GUILD_NOT_FOUND.
type ModuleModerationHandler struct {
	Repo mongorepo.ModuleModerationRepo
}

// NewModuleModerationHandler builds the handler.
func NewModuleModerationHandler(repo mongorepo.ModuleModerationRepo) *ModuleModerationHandler {
	return &ModuleModerationHandler{Repo: repo}
}

// Get mirrors `getModuleModerationController`. Returns the full moderation subdoc
// (default-filled + normalised) with source headers stamped, or a 400
// MODULE_NOT_FOUND with `data:null` + source when the guild has no moderation
// block yet. Honors the optional `?force=true` query that evicts the cache before
// reading (the Node controller parses it via `querySkipCacheValidation` and
// forwards it to `findModule({ force })`).
func (h *ModuleModerationHandler) Get(c fiber.Ctx) error {
	r := result.New[*dbguild.ModuleModeration]()
	ctx := c.Context()

	force, _ := strconv.ParseBool(c.Query("force"))

	sourced, err := h.Repo.FindModule(ctx, c.Params("bot_id"), c.Params("guild_id"), force)
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeInternal,
			Context:    apierrors.ContextSystem,
			StatusCode: 500,
		}))
		return reply(c, r)
	}
	// Stamp the source from the repo even on the not-found path — the FindModule
	// no-document branch still carries "db" / the module detail, mirroring the
	// Node applySourceAndStash(sourced{data:null}).
	if sourced != nil {
		r.SetSource(result.Source(sourced.Source), sourced.SourceDetail)
	}
	if sourced == nil || sourced.Data.SchemaVersion == 0 {
		r.SetData(nil)
		r.AddError(apierrors.MongoMessage("Module not found", apierrors.CodeModuleNotFound))
		return reply(c, r)
	}
	d := sourced.Data
	r.SetData(&d)
	return reply(c, r)
}

// Patch mirrors `patchModuleModerationController`. Strict body
// (DisallowUnknownFields, matching the zod `.strict()`) validates the shape;
// the SAME body is then re-decoded as a raw `map[string]any` so key PRESENCE
// survives, and the repo MergeDeepJSON-merges it into the current subdoc — a
// partial PATCH preserves untouched fields, nested-block siblings, and per-key
// `commands` overrides, and explicit `false`/`0`/`null` leaves are APPLIED
// (mirrors the Node `mergeDeep`, which only skips `undefined`). An empty body
// `{}` is a no-op that still bumps schema_version + updated_at (Node returns
// 200). A missing guild → 400 MODULE_NOT_FOUND with `data:null`.
func (h *ModuleModerationHandler) Patch(c fiber.Ctx) error {
	r := result.New[*dbguild.ModuleModeration]()
	ctx := c.Context()

	var body validations.UpdateModuleModerationBody
	dec := json.NewDecoder(bytes.NewReader(c.Body()))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&body); err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeValidation,
			Context:    apierrors.ContextAPI,
			StatusCode: 400,
		}))
		return reply(c, r)
	}

	// Re-decode the (already validated) body as a raw map so key presence
	// survives — explicit false/0/null must reach the merge (Node parity).
	patch, err := patchMap(c.Body())
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeValidation,
			Context:    apierrors.ContextAPI,
			StatusCode: 400,
		}))
		return reply(c, r)
	}

	sourced, err := h.Repo.Update(ctx, c.Params("bot_id"), c.Params("guild_id"), patch)
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeInternal,
			Context:    apierrors.ContextSystem,
			StatusCode: 500,
		}))
		return reply(c, r)
	}
	if sourced == nil || sourced.Data.SchemaVersion == 0 {
		// Node's update-null branch stamps db + a source detail + data:null
		// before throwing MODULE_NOT_FOUND. The repo returns a bare nil here,
		// so stamp the source by hand.
		r.SetSource(result.SourceDB, sourceDetailModerationDBNotFound)
		r.SetData(nil)
		r.AddError(apierrors.MongoMessage("Module not found", apierrors.CodeModuleNotFound))
		return reply(c, r)
	}
	d := sourced.Data
	r.SetData(&d)
	r.SetSource(result.Source(sourced.Source), sourced.SourceDetail)
	return reply(c, r)
}

package handlers

import (
	"context"
	"reflect"
	"strings"

	"github.com/gofiber/fiber/v3"
	"github.com/rs/zerolog/log"

	"kena.bot/api-db-go/internal/domain/dbguild"
	apierrors "kena.bot/api-db-go/internal/domain/errors"
	"kena.bot/api-db-go/internal/domain/validations"
	"kena.bot/api-db-go/internal/infrastructure/mongorepo"
	"kena.bot/api-db-go/internal/shared/result"
)

// Music field whitelist. Must match the keys of `dbguild.ModuleMusic`
// 1:1 (otherwise a typo in the path would 200 with `null` instead of
// 400). Kept as a sorted-slice comparison via a map for O(1) lookup.
var musicFieldWhitelist = map[string]struct{}{
	"schema_version":       {},
	"enabled":              {},
	"enabled_since":        {},
	"max_song_duration":    {},
	"loop":                 {},
	"volume":               {},
	"radio_mode":           {},
	"message_retention":    {},
	"pinned_now_playing":   {},
	"voice_status_enabled": {},
	"bot_pool_enabled":     {},
	"enhanced_search":      {},
	"auto_delete_commands": {},
	"audio_quality":        {},
	"commands_global":      {},
	"commands":             {},
	"text_channels":        {},
	"voice_channels":       {},
	"dj":                   {},
	"recommended_artists":  {},
}

// ModuleMusicHandler wires the three music endpoints behind a single
// struct so the router can mount them with a single instance.
//
// Mirrors `module-music-controller.ts` in the Node service.
type ModuleMusicHandler struct {
	Repo mongorepo.ModuleMusicRepo
	// Lavalink is nil only when a caller has no db-8 writer at all (the tests).
	// A FAILED dial does NOT arrive here as nil: main.go wraps the nil client in
	// a nil-safe cache, so the call still happens and returns
	// ErrLavalinkUnavailable, which the PATCH logs. That is deliberate — a
	// toggle that did not reach Redis must leave a per-request trace, not just
	// the one boot line. This side-effect went unnoticed for exactly that
	// reason: no signal at the point of failure.
	Lavalink PlayerPersistenceWriter
}

// PlayerPersistenceWriter is the db-8 side-effect the music PATCH needs to keep
// Redis in step with `radio_mode.enabled`. An interface rather than the concrete
// *redis.LavalinkCache so the handler stays testable and so a failed dial can be
// wired as nil.
type PlayerPersistenceWriter interface {
	SetPlayerPersistent(ctx context.Context, botID, guildID string, persistent bool) error
}

// NewModuleMusicHandler builds the handler. `lavalink` is the optional db-8
// writer; pass nil to skip the 24/7 propagation. It is a REQUIRED parameter
// rather than a field callers may forget to set, on purpose: the defect this
// fixes was precisely that the side-effect was documented but never wired.
func NewModuleMusicHandler(repo mongorepo.ModuleMusicRepo, lavalink PlayerPersistenceWriter) *ModuleMusicHandler {
	return &ModuleMusicHandler{Repo: repo, Lavalink: lavalink}
}

// Get mirrors `getModuleMusicController`. Returns the full music subdoc
// (default-filled) with source headers stamped.
func (h *ModuleMusicHandler) Get(c fiber.Ctx) error {
	r := result.New[*dbguild.ModuleMusic]()
	ctx := c.Context()

	sourced, err := h.Repo.FindModule(ctx, c.Params("bot_id"), c.Params("guild_id"))
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeInternal,
			Context:    apierrors.ContextSystem,
			StatusCode: 500,
		}))
		return reply(c, r)
	}
	if sourced == nil || sourced.Data.SchemaVersion == 0 {
		// data:null parity — the Node getModuleMusicController runs
		// applySourceAndStash(sourced{data:null}) before throwing
		// MODULE_NOT_FOUND, so the envelope carries `"data":null`.
		r.SetData(nil)
		r.AddError(apierrors.MongoMessage("Module not found", apierrors.CodeModuleNotFound))
		return reply(c, r)
	}
	d := sourced.Data
	r.SetData(&d)
	r.SetSource(result.Source(sourced.Source), sourced.SourceDetail)
	return reply(c, r)
}

// GetField mirrors `getModuleMusicFieldController`. Returns a single
// field value via `data: <single value>`. Returns 400 MODULE_NOT_FOUND
// when the guild has no module music yet.
// GetRadioModeGuilds lists this bot's guilds with 24/7 enabled and the channel
// each one is configured to sit in.
//
// Bot-scoped, so it hangs off `/bots/:bot_id/modules/music/...` rather than the
// per-guild prefix — same shape as the modmail `active-guild` endpoint.
//
// An empty list is a 200 with `data: []`, NOT an error: "this bot has no 24/7
// guilds" is a perfectly ordinary answer, and the caller (the music module's
// boot reconciliation) has to be able to tell it apart from "the query failed"
// — if it could not, a database hiccup would look like "nobody wants 24/7" and
// the reconciliation would silently do nothing.
func (h *ModuleMusicHandler) GetRadioModeGuilds(c fiber.Ctx) error {
	r := result.New[any]()

	guilds, err := h.Repo.FindRadioModeGuilds(c.Context(), c.Params("bot_id"))
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeInternal,
			Context:    apierrors.ContextSystem,
			StatusCode: 500,
		}))
		return reply(c, r)
	}

	r.SetData(guilds)
	// Literal en vez de la constante de `mongo`: este handler sólo depende de
	// `mongorepo` (interfaces) para poder testearse con fakes, e importar el
	// paquete de infraestructura sólo por una cadena rompería esa separación.
	// El valor es el mismo que estampa el repositorio en sus lecturas de Mongo.
	r.SetSource(result.SourceDB, "mongo.guild.module_music")
	return reply(c, r)
}

func (h *ModuleMusicHandler) GetField(c fiber.Ctx) error {
	r := result.New[any]()
	ctx := c.Context()

	field := c.Params("field")
	if _, ok := musicFieldWhitelist[field]; !ok {
		r.AddError(apierrors.Validation("field must be one of the music keys", ""))
		return reply(c, r)
	}

	sourced, err := h.Repo.FindField(ctx, c.Params("bot_id"), c.Params("guild_id"), field)
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeInternal,
			Context:    apierrors.ContextSystem,
			StatusCode: 500,
		}))
		return reply(c, r)
	}
	if sourced == nil || sourced.Data == nil {
		// data:null parity — the Node getModuleMusicFieldController runs
		// applySourceAndStash(sourced{data:null}) before throwing
		// MODULE_NOT_FOUND. The `any` payload already omits `data` when
		// unset, so stamp an explicit null.
		r.SetData(nil)
		r.AddError(apierrors.MongoMessage("Module not found", apierrors.CodeModuleNotFound))
		return reply(c, r)
	}
	r.SetData(sourced.Data)
	r.SetSource(result.Source(sourced.Source), sourced.SourceDetail)
	return reply(c, r)
}

// Patch mirrors `patchModuleMusicController`. Strict body — unknown
// JSON keys fail `c.Bind().Body(&body)` with a TypeMismatch error.
//
// The Node service runs a `GuildRepository.checkGuildExists` first.
// We rely on Mongo's no-document response when the guild is missing;
// the repository returns `nil, nil` and the handler emits UNKNOWN_ERROR.
func (h *ModuleMusicHandler) Patch(c fiber.Ctx) error {
	r := result.New[*dbguild.ModuleMusic]()
	ctx := c.Context()

	var body validations.UpdateModuleMusicBody
	if err := c.Bind().Body(&body); err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeValidation,
			Context:    apierrors.ContextAPI,
			StatusCode: 400,
		}))
		return reply(c, r)
	}

	set := body.Set()
	if len(set) == 0 {
		// Empty body or no applicable fields → 400. Strict parity with
		// the bots-guilds Update handler.
		r.AddError(apierrors.Unknown(""))
		return reply(c, r)
	}

	sourced, err := h.Repo.Update(ctx, c.Params("bot_id"), c.Params("guild_id"), set)
	if err != nil {
		r.AddError(apierrors.New(apierrors.Props{
			Message:    err.Error(),
			Type:       apierrors.TypeInternal,
			Context:    apierrors.ContextSystem,
			StatusCode: 500,
		}))
		return reply(c, r)
	}
	if sourced == nil || sourced.Data.SchemaVersion == 0 {
		// data:null parity — the Node patchModuleMusicController runs
		// applySourceAndStash(sourced{data:null}) before throwing
		// UNKNOWN_ERROR on the update-null branch (a missing guild makes
		// Mongo return no document). Keep the UNKNOWN_ERROR code; only the
		// data-presence changes.
		r.SetData(nil)
		r.AddError(apierrors.Unknown(""))
		return reply(c, r)
	}

	// Side-effect on db 8. The dashboard just toggled 24/7, and Redis holds the
	// flag that keeps a live player's keys out of the TTL cycle; without this the
	// PATCH updated Mongo and left the flag lying. Best-effort by design: Mongo is
	// the source of truth and has already committed, so a Redis failure must not
	// turn a successful PATCH into a 500 — and `PlayerStart` resyncs the flag from
	// `radio_mode.enabled` on the next player start regardless.
	if enabled := body.RadioModeEnabled(); enabled != nil && h.Lavalink != nil {
		botID, guildID := c.Params("bot_id"), c.Params("guild_id")
		if err := h.Lavalink.SetPlayerPersistent(ctx, botID, guildID, *enabled); err != nil {
			log.Warn().Err(err).
				Str("bot_id", botID).
				Str("guild_id", guildID).
				Bool("radio_mode_enabled", *enabled).
				Msg("radio_mode PATCH committed to mongo but the 24/7 flag on db 8 was not updated")
		}
	}
	d := sourced.Data
	r.SetData(&d)
	r.SetSource(result.Source(sourced.Source), sourced.SourceDetail)
	return reply(c, r)
}

// ensureMusicWhitelistMatchesType is a build-time assertion that the
// musicFieldWhitelist map covers every JSON-tagged field of ModuleMusic.
// Run at init via blank assignment; fails compilation if drift occurs.
var _ = func() bool {
	want := map[string]struct{}{}
	t := reflect.TypeOf(struct {
		SchemaVersion      int      `json:"schema_version"`
		Enabled            bool     `json:"enabled"`
		EnabledSince       any      `json:"enabled_since"`
		MaxSongDuration    int      `json:"max_song_duration"`
		Loop               string   `json:"loop"`
		Volume             int      `json:"volume"`
		RadioMode          any      `json:"radio_mode"`
		MessageRetention   bool     `json:"message_retention"`
		PinnedNowPlaying   bool     `json:"pinned_now_playing"`
		VoiceStatusEnabled bool     `json:"voice_status_enabled"`
		BotPoolEnabled     bool     `json:"bot_pool_enabled"`
		EnhancedSearch     bool     `json:"enhanced_search"`
		AutoDeleteCommands []string `json:"auto_delete_commands"`
		AudioQuality       string   `json:"audio_quality"`
		CommandsGlobal     any      `json:"commands_global"`
		Commands           any      `json:"commands"`
		TextChannels       any      `json:"text_channels"`
		VoiceChannels      any      `json:"voice_channels"`
		DJ                 any      `json:"dj"`
		RecommendedArtists []string `json:"recommended_artists"`
	}{})
	for i := 0; i < t.NumField(); i++ {
		tag := strings.SplitN(t.Field(i).Tag.Get("json"), ",", 2)[0]
		if tag != "" {
			want[tag] = struct{}{}
		}
	}
	if len(want) != len(musicFieldWhitelist) {
		return false
	}
	for k := range want {
		if _, ok := musicFieldWhitelist[k]; !ok {
			return false
		}
	}
	return true
}()

