// UpdateModuleGiveawayBody mirrors the Node `updateModuleGiveawaySchema`
// (a `.strict()` object of `.optional()` fields). The handler decodes
// this with `DisallowUnknownFields` (matching the zod `.strict()` —
// unknown keys are a 400) and then re-decodes the SAME raw body as
// `map[string]any`, which the repository merges into the existing
// subdoc via `mongo.MergeDeepJSON` by KEY PRESENCE: a key absent in
// the body is left alone; an explicit `false`/`0`/`""`/`null` is
// applied and overrides the stored value; nested objects recurse;
// slices replace wholesale; maps merge per-key.
//
// UNLIKE the READ schema, the PATCH schema exposes NO `schema_version`
// / `updated_at` — those are stamped by the repo on every write. Every
// other READ field IS patchable here (the READ and PATCH catalogs
// otherwise match).
//
// Because merge is presence-based, the five TS `string | null`
// (`default_channel_id`, `color`, `emoji`, `ping_role_id`,
// `default_host_id`) work as in Node: omitting the key preserves the
// stored value; sending `null` clears it to null; sending a string
// overwrites it. So a `*string` field no longer needs any special
// "pass-through" handling — the raw map carries the same information.
//
// REMAINING CAVEATS (inherited from the old MergeDeep mold, NOT from
// presence-based behaviour):
//   - Go's json decoder does NOT enforce zod's REQUIRED-ness inside a
//     present nested object, so a partial nested object that Node would
//     400 is accepted here and the missing leaves stay zero — the same
//     non-strict-required behaviour every Go module body has.
//   - The zod value constraints (`emoji` max 64, `button_label` max 80,
//     `winner_message`/`messages` values max 4000, non-nullability of
//     `button_label`/`winner_message`) are NOT enforced here — Go's
//     decoder validates structure/unknown-keys, not string length or a
//     `null` sent to a non-nullable field. Same as every other Go
//     module body.
type UpdateModuleGiveawayBody struct {
	Enabled          *bool              `json:"enabled,omitempty"`
	DefaultChannelID *string            `json:"default_channel_id,omitempty"`
	Color            *string            `json:"color,omitempty"`
	Emoji            *string            `json:"emoji,omitempty"`
	ButtonLabel      *string            `json:"button_label,omitempty"`
	PingRoleID       *string            `json:"ping_role_id,omitempty"`
	DefaultHostID    *string            `json:"default_host_id,omitempty"`
	DMWinners        *bool              `json:"dm_winners,omitempty"`
	AllowReroll      *bool              `json:"allow_reroll,omitempty"`
	WinnerMessage    *string            `json:"winner_message,omitempty"`
	ShowWinners      *bool              `json:"show_winners,omitempty"`
	ShowEntries      *bool              `json:"show_entries,omitempty"`
	ShowEnd          *bool              `json:"show_end,omitempty"`
	ShowHost         *bool              `json:"show_host,omitempty"`
	Messages         *map[string]string `json:"messages,omitempty"`
}

