191	// enum fields the way `z.enum(...)` does. Shared by ResolveCreate (POST) and
192	// ResolveUpdate (PATCH) — both apply per-field presence defaults identically.
193	func resolvePresence(p *BotPresenceBody) (dbbot.Presence, *apierrors.CustomError) {
194		out := dbbot.DefaultPresence()
