		}
		for _, id := range ids {
			if !snowflakeRe.MatchString(id) {
				return zodItemError("Must be a Discord snowflake (17–20 digits)", "hidden_module_testers")
			}
		}
	}
	return nil
}

// validateCustomName mirrors `z.string().max(64)` en api-gateway. Igual que
// `ValidateDeveloperID`, el corte es por len() en bytes — suficiente para un
// alias de catálogo y coherente con el resto del fichero.
func validateCustomName(name string) *apierrors.CustomError {
	if len(name) > 64 {
		return zodItemError("Too big: expected string to have <=64 characters", "custom_name")
	}
	return nil
}

// validateVisibility mirrors `z.enum(["public","private"])`.
func validateVisibility(v string) (dbbot.DBBotVisibility, *apierrors.CustomError) {
	vis := dbbot.DBBotVisibility(v)
	if !vis.Valid() {
		return "", zodItemError(`Invalid option: expected one of "public"|"private"`, "visibility")
	}
	return vis, nil
}

// resolvePresence starts from `DefaultPresence()` (the botMock defaults) and
// overrides only the inner fields the client actually sent, validating the two
// enum fields the way `z.enum(...)` does. Shared by ResolveCreate (POST) and
// ResolveUpdate (PATCH) — both apply per-field presence defaults identically.
func resolvePresence(p *BotPresenceBody) (dbbot.Presence, *apierrors.CustomError) {
	out := dbbot.DefaultPresence()
	if p == nil {
		return out, nil
	}
	if p.Status != nil {
		s := dbbot.DBPresenceStatus(*p.Status)
		if !s.Valid() {
			return out, zodItemError(`Invalid option: expected one of "online"|"idle"|"offline"|"dnd"`, "presence.status")
		}
		out.Status = s
	}
	if p.ActivityType != nil {
		a := dbbot.DBPresenceActivity(*p.ActivityType)
		if !a.Valid() {
			return out, zodItemError(`Invalid option: expected one of "Playing"|"Streaming"|"Listening"|"Watching"|"Competing"`, "presence.activity_type")
		}
		out.ActivityType = a
	}
	if p.ActivityName != nil {
		out.ActivityName = *p.ActivityName
	}
	if p.ActivityURL != nil {
		out.ActivityURL = *p.ActivityURL
	}
	return out, nil
}

// resolveWelcome starts from `DefaultWelcome()` and overrides only what the
// client actually sent, validating the template id against the catalog the way
// `z.enum(...)` does. Same shape as `resolvePresence`: shared by POST and
// PATCH, and a present `welcome` always REPLACES the whole subdocument (the
// omitted inner fields come back as their defaults, not as the stored value).
func resolveWelcome(w *BotWelcomeBody) (dbbot.Welcome, *apierrors.CustomError) {
	out := dbbot.DefaultWelcome()
	if w == nil {
		return out, nil
	}
	if verr := applyWelcomeMessage(&out.DM, w.DM, "welcome.dm"); verr != nil {
		return out, verr
	}
	if verr := applyWelcomeMessage(&out.Channel, w.Channel, "welcome.channel"); verr != nil {
		return out, verr
	}
	return out, nil
}

