package handlers

import (
	"github.com/gofiber/fiber/v3"

	"kena.bot/api-db-go/internal/domain/dbauditlog"
	"kena.bot/api-db-go/internal/domain/validations"
	"kena.bot/api-db-go/internal/infrastructure/mongorepo"
	"kena.bot/api-db-go/internal/shared/result"
)

// auditLogSourceDetail mirrors the value the /audit-log endpoints stamp via
// `r.SetSource(result.SourceDB, ...)` — Mongo-only, no cache, so every
// response is db-sourced (same posture as deezerSourceDetail).
const auditLogSourceDetail = "mongo.audit_log"

// AuditLogHandler wires the two `/audit-log` endpoints — GET (paginated,
// filtered list) and POST (append a row) — behind the repository interface.
// Vertical SIN contrapartida en el Node api-db (el registro de actividad del
// panel es nuevo): usa el `reply[T]` / `WriteError` compartidos de
// bots_guilds_handler.go, no una cola bespoke tipo `deezerReply` — esas sólo
// existen en verticales portados de Node por paridad byte a byte, y este no
// lo es.
type AuditLogHandler struct {
	Repo mongorepo.AuditLogRepo
}

// NewAuditLogHandler builds the handler.
func NewAuditLogHandler(repo mongorepo.AuditLogRepo) *AuditLogHandler {
	return &AuditLogHandler{Repo: repo}
}

// List — GET /audit-log?guild_id=&bot_id=&actor_id=&action=&status=&limit=&offset=.
// `guild_id` es obligatorio; una página vacía sigue serializando `rows: []`.
func (h *AuditLogHandler) List(c fiber.Ctx) error {
	r := result.New[*dbauditlog.ListResponse]()
	ctx := c.Context()

	filter, limit, offset, verr := validations.ParseAuditLogListQuery(
		c.Query("guild_id"), c.Query("bot_id"), c.Query("actor_id"),
		c.Query("action"), c.Query("status"), c.Query("limit"), c.Query("offset"),
	)
	if verr != nil {
		r.AddError(verr)
		return reply(c, r)
	}

	resp, err := h.Repo.FindAll(ctx, filter, limit, offset)
	if err != nil {
		WriteError(c, r, err)
		return reply(c, r)
	}
	r.SetData(&resp)
	r.SetSource(result.SourceDB, auditLogSourceDetail)
	return reply(c, r)
}

// Create — POST /audit-log. Inserta la fila y poda el histórico del guild de
// vuelta a dbauditlog.GuildRetention como efecto lateral (ver
// AuditLogRepository.Create). Siempre 201 en éxito.
func (h *AuditLogHandler) Create(c fiber.Ctx) error {
	r := result.New[*dbauditlog.Document]()
	ctx := c.Context()

	in, verr := validations.ParseAuditLogCreate(c.Body())
	if verr != nil {
		r.AddError(verr)
		return reply(c, r)
	}

	doc, err := h.Repo.Create(ctx, in)
	if err != nil {
		WriteError(c, r, err)
		return reply(c, r)
	}
	r.SetData(doc)
	r.SetSource(result.SourceDB, auditLogSourceDetail)
	return replyWithStatus(c, r, fiber.StatusCreated)
}

