// TestModerationPatch_EmptyEnum_400 🛡️ — a closed-enum leaf sent as `""`
// (the exact shape a real corrupted guild document had — ver
// AUDITORIA-fallos-silenciosos-2026-08-11.md, hallazgos 10/13/14) is rejected
// with 400 before the repo is called, instead of being persisted looking
// "configured" while the bot silently reinterprets it as its most permissive
// branch.
func TestModerationPatch_EmptyEnum_400(t *testing.T) {
	cases := []struct {
		name string
		body map[string]any
	}{
		{"command_mode", map[string]any{"command_mode": ""}},
		{"mute.mode", map[string]any{"mute": map[string]any{"mode": ""}}},
		{"automod.mentions.action", map[string]any{"automod": map[string]any{"mentions": map[string]any{"action": ""}}}},
		{"automod.attachments.action", map[string]any{"automod": map[string]any{"attachments": map[string]any{"action": ""}}}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			repo := &mocks.FakeModuleModerationRepo{}
			app := newModerationMockApp(repo)
			status, _, body := doModuleReq(t, app, "PATCH", "/bots/b1/guilds/g1/modules/moderation/", "Bearer "+testSecret, tc.body)
			if status != 400 {
				t.Fatalf("status = %d, want 400\nbody: %s", status, body)
			}
			if len(repo.UpdateCalls) != 0 {
				t.Fatalf("UpdateCalls = %d, want 0 (handler must reject before the repo)", len(repo.UpdateCalls))
			}
		})
	}
}

// TestModerationPatch_InvalidEnum_400 🛡️ — same as above but for a value
// outside the closed set entirely (not just empty), confirming the check is
// a real allowlist and not just an empty-string special case.
func TestModerationPatch_InvalidEnum_400(t *testing.T) {
	repo := &mocks.FakeModuleModerationRepo{}
	app := newModerationMockApp(repo)
	status, _, body := doModuleReq(t, app, "PATCH", "/bots/b1/guilds/g1/modules/moderation/", "Bearer "+testSecret,
		map[string]any{"command_mode": "bogus"})
	if status != 400 {
		t.Fatalf("status = %d, want 400\nbody: %s", status, body)
	}
	if len(repo.UpdateCalls) != 0 {
		t.Fatalf("UpdateCalls = %d, want 0 (handler must reject before the repo)", len(repo.UpdateCalls))
	}
}

// TestModerationPatch_PartialMuteWithoutMode_NotRejected 🛡️ — a partial
// `mute` PATCH that omits `mode` on purpose (only touching `role_id`) must
// NOT be rejected: `MergeDeepJSON` leaves the stored `mode` untouched, so an
// absent key is not the same as an explicit `""` and the enum check must
