		map[string]any{
			"command_mode":   "slash",
			"log_channel_id": "chan-1",
			"mute":           map[string]any{"mode": "role"},
			"commands":       map[string]any{"ban": map[string]any{"enabled": true}},
			"automod":        map[string]any{"mentions": map[string]any{"max_mentions": 5}},
		})
	if status != 200 {
		t.Fatalf("status = %d, want 200\nbody: %s", status, body)
	}
	if len(repo.UpdateCalls) != 1 {
		t.Fatalf("UpdateCalls = %d, want 1", len(repo.UpdateCalls))
	}
	got := repo.UpdateCalls[0]
	if got["log_channel_id"] != "chan-1" {
		t.Fatalf("patch[log_channel_id] = %v, want chan-1", got["log_channel_id"])
	}
	if got["command_mode"] != "slash" {
		t.Fatalf("patch[command_mode] = %v, want slash", got["command_mode"])
	}
	mute, ok := got["mute"].(map[string]any)
	if !ok || mute["mode"] != "role" {
		t.Fatalf("patch[mute] = %v, want map[mode:role]", got["mute"])
	}
	if _, ok := mute["role_id"]; ok {
		t.Fatalf("patch[mute][role_id] unexpectedly present: %+v", mute)
	}
	commands, ok := got["commands"].(map[string]any)
	ban, banOK := commands["ban"].(map[string]any)
	if !ok || !banOK || ban["enabled"] != true {
		t.Fatalf("patch[commands] = %v, want ban.enabled=true", got["commands"])
	}
	automod, ok := got["automod"].(map[string]any)
	mentions, mentionsOK := automod["mentions"].(map[string]any)
	if !ok || !mentionsOK || mentions["max_mentions"] != float64(5) {
		t.Fatalf("patch[automod] = %v, want mentions.max_mentions=5", got["automod"])
	}
	for _, key := range []string{"enabled", "track_native_actions"} {
		if _, ok := got[key]; ok {
			t.Fatalf("patch[%s] unexpectedly present in raw JSON patch: %+v", key, got)
		}
	}
}

// TestModerationPatch_EmptyBody_NoOp 🛡️ — an empty `{}` body is forwarded as
// an empty patch and still returns 200 with the schema-bumped subdoc (Node parity).
func TestModerationPatch_EmptyBody_NoOp(t *testing.T) {
	repo := &mocks.FakeModuleModerationRepo{
		UpdateFn: func(_, _ string, _ map[string]any) (*mongorepo.Sourced[dbguild.ModuleModeration], error) {
			return moderationSourced(mocks.NewModuleModeration(), "db", "mongo.guild.module_moderation"), nil
		},
	}
	app := newModerationMockApp(repo)
	status, _, body := doModuleReq(t, app, "PATCH", "/bots/b1/guilds/g1/modules/moderation/", "Bearer "+testSecret, map[string]any{})
	if status != 200 {
		t.Fatalf("status = %d, want 200 (empty body is a no-op, Node returns 200)\nbody: %s", status, body)
	}
	if len(repo.UpdateCalls) != 1 {
		t.Fatalf("UpdateCalls = %d, want 1", len(repo.UpdateCalls))
	}
	if got := repo.UpdateCalls[0]; len(got) != 0 {
		t.Fatalf("empty body should forward an empty patch, got %+v", got)
	}
}

// TestModerationPatch_BadKey_400 🛡️ — an unknown JSON key is rejected with 400
// (DisallowUnknownFields, matching the zod `.strict()`) and the repo is NOT
// called.
func TestModerationPatch_BadKey_400(t *testing.T) {
	repo := &mocks.FakeModuleModerationRepo{}
	app := newModerationMockApp(repo)
	status, hdr, body := doModuleReq(t, app, "PATCH", "/bots/b1/guilds/g1/modules/moderation/", "Bearer "+testSecret, map[string]any{"bogus": 1})
	if status != 400 {
		t.Fatalf("status = %d, want 400 (strict body rejects unknown key)\nbody: %s", status, body)
	}
	if got := hdr.Get(handlers.HeaderErrorType); got != "API" {
		t.Fatalf("x-error-type = %q, want API\nbody: %s", got, body)
	}
	if len(repo.UpdateCalls) != 0 {
		t.Fatalf("UpdateCalls = %d, want 0 (handler must reject before the repo)", len(repo.UpdateCalls))
	}
}

// TestModerationPatch_Flows_Accepted 🛡️ — regresión del contrato de flujos:
// un PATCH con `flows` (v4) YA NO es rechazado por `DisallowUnknownFields` —
// antes de añadir el campo `Flows` a `UpdateModuleModerationBody` esto daba
// 400 igual que `TestModerationPatch_BadKey_400`. La forma completa del
// flujo (con `scope`/`trigger`/`steps` anidados) debe pasar el decode
// estricto sin que ninguna de sus claves cuente como "desconocida", y el
// mapa crudo reenviado al repo debe conservar `flows` por PRESENCIA.
func TestModerationPatch_Flows_Accepted(t *testing.T) {
	repo := &mocks.FakeModuleModerationRepo{
		UpdateFn: func(_, _ string, _ map[string]any) (*mongorepo.Sourced[dbguild.ModuleModeration], error) {
			return moderationSourced(mocks.NewModuleModeration(), "db", "mongo.guild.module_moderation"), nil
		},
	}
	app := newModerationMockApp(repo)
	flow := map[string]any{
		"id": "f1", "name": "Test Flow", "enabled": true,
		"trigger": map[string]any{"type": "message_sent", "params": map[string]any{}},
		"scope": map[string]any{
			"channels":              map[string]any{"mode": "all_except", "ids": []any{}},
			"categories":            map[string]any{"mode": "all_except", "ids": []any{}},
			"roles":                 map[string]any{"mode": "all_except", "ids": []any{}},
			"ignore_bots":           true,
			"ignore_admins":         true,
			"cooldown_seconds":      0,
			"rate_limit_per_minute": 0,
		},
		"setup":          []any{},
		"condition_mode": "and",
		"conditions":     []any{},
		"steps": []any{
			map[string]any{"id": "s1", "type": "warn_member", "params": map[string]any{"reason": "spam"}},
		},
		"branches":    []any{},
		"debug_until": nil,
		"created_at":  "2026-01-01T00:00:00.000Z",
		"updated_at":  "2026-01-01T00:00:00.000Z",
	}
	status, _, body := doModuleReq(t, app, "PATCH", "/bots/b1/guilds/g1/modules/moderation/", "Bearer "+testSecret,
		map[string]any{"flows": []any{flow}})
	if status != 200 {
		t.Fatalf("status = %d, want 200 (flows ya no debe ser una clave desconocida)\nbody: %s", status, body)
	}
	if len(repo.UpdateCalls) != 1 {
		t.Fatalf("UpdateCalls = %d, want 1", len(repo.UpdateCalls))
	}
	rawFlows, ok := repo.UpdateCalls[0]["flows"]
	if !ok {
		t.Fatalf("el patch reenviado al repo no trae la clave \"flows\": %+v", repo.UpdateCalls[0])
	}
	flows, ok := rawFlows.([]any)
	if !ok || len(flows) != 1 {
		t.Fatalf("flows reenviado = %T (%v), want un slice de 1 elemento", rawFlows, rawFlows)
	}
}

// TestModerationPatch_ReadOnlyKey_400 🛡️ — the READ-schema keys NOT in the PATCH
// schema (`schema_version`, `updated_at`) are rejected: the update body omits
// them, so the strict decoder treats them as unknown keys.
func TestModerationPatch_ReadOnlyKey_400(t *testing.T) {
	for _, key := range []string{"schema_version", "updated_at"} {
		repo := &mocks.FakeModuleModerationRepo{}
		app := newModerationMockApp(repo)
		var val any = "2026-01-01T00:00:00.000Z"
		if key == "schema_version" {
			val = 2
		}
		status, _, body := doModuleReq(t, app, "PATCH", "/bots/b1/guilds/g1/modules/moderation/", "Bearer "+testSecret, map[string]any{key: val})
		if status != 400 {
			t.Fatalf("PATCH {%s} status = %d, want 400 (not a PATCH-schema field)\nbody: %s", key, status, body)
		}
		if len(repo.UpdateCalls) != 0 {
			t.Fatalf("PATCH {%s} UpdateCalls = %d, want 0", key, len(repo.UpdateCalls))
		}
	}
}

// TestModerationPatch_InvalidType_400 🛡️ — a type mismatch on a known key is a 400
// (the strict decoder rejects it before the repo).
func TestModerationPatch_InvalidType_400(t *testing.T) {
	repo := &mocks.FakeModuleModerationRepo{}
	app := newModerationMockApp(repo)
	status, _, body := doModuleReq(t, app, "PATCH", "/bots/b1/guilds/g1/modules/moderation/", "Bearer "+testSecret, map[string]any{"enabled": "not-a-bool"})
	if status != 400 {
		t.Fatalf("status = %d, want 400\nbody: %s", status, body)
	}
	if len(repo.UpdateCalls) != 0 {
		t.Fatalf("UpdateCalls = %d, want 0", len(repo.UpdateCalls))
	}
}

// TestModerationPatch_GuildMissing_NotFound_DataNull 🛡️ — the repo returns nil
// (guild missing) → 400 MODULE_NOT_FOUND with data:null and source=db.
func TestModerationPatch_GuildMissing_NotFound_DataNull(t *testing.T) {
	repo := &mocks.FakeModuleModerationRepo{
		UpdateFn: func(_, _ string, _ map[string]any) (*mongorepo.Sourced[dbguild.ModuleModeration], error) {
			return nil, nil
		},
	}
	app := newModerationMockApp(repo)
	status, hdr, body := doModuleReq(t, app, "PATCH", "/bots/b1/guilds/g1/modules/moderation/", "Bearer "+testSecret, map[string]any{"enabled": true})
	if status != 400 {
		t.Fatalf("status = %d, want 400\nbody: %s", status, body)
	}
	if !bytes.Contains(body, []byte("MODULE_NOT_FOUND")) {
		t.Fatalf("body should contain MODULE_NOT_FOUND: %s", body)
	}
	if !bytes.Contains(body, []byte(`"data":null`)) {
		t.Fatalf("not-found body must carry data:null: %s", body)
	}
	if got := hdr.Get(handlers.HeaderResultSource); got != "db" {
		t.Fatalf("X-Result-Source = %q, want db", got)
	}
}

// TestModerationPatch_RepoError_500 🛡️ — a repo error during PATCH surfaces 500.
func TestModerationPatch_RepoError_500(t *testing.T) {
	repo := &mocks.FakeModuleModerationRepo{
		UpdateFn: func(_, _ string, _ map[string]any) (*mongorepo.Sourced[dbguild.ModuleModeration], error) {
