	if status != 500 {
		t.Fatalf("status = %d, want 500\nbody: %s", status, body)
	}
	if got := hdr.Get(handlers.HeaderErrorType); got != "SYSTEM" {
		t.Fatalf("x-error-type = %q, want SYSTEM", got)
	}
}

// TestEnabledNoQuery_IncludesModeration 🛡️ — with moderation wired via
// WithModeration and enabled=true, the no-query /enabled fan-out reports it.
func TestEnabledNoQuery_IncludesModeration(t *testing.T) {
	music := &fakeMusicRepo{findModuleFn: func(string, string) *mongorepo.Sourced[dbguild.ModuleMusic] {
		return &mongorepo.Sourced[dbguild.ModuleMusic]{Data: mocks.NewModuleMusic(), Source: "db"}
	}}
	greeter := &fakeGreeterRepo{findModuleFn: func(string, string, bool) *mongorepo.Sourced[dbguild.ModuleGreeter] {
		return &mongorepo.Sourced[dbguild.ModuleGreeter]{Data: mocks.NewModuleGreeter(), Source: "db"}
	}}
	logs := &fakeLogsRepo{findModuleFn: func(string, string) *mongorepo.Sourced[dbguild.ModuleLogs] {
		return &mongorepo.Sourced[dbguild.ModuleLogs]{Data: mocks.NewModuleLogs(), Source: "db"}
	}}
	moderation := &mocks.FakeModuleModerationRepo{FindModuleFn: func(string, string, bool) (*mongorepo.Sourced[dbguild.ModuleModeration], error) {
		d := mocks.NewModuleModeration()
		d.Enabled = true
		return moderationSourced(d, "db", "mongo.guild.module_moderation"), nil
	}}

	app := fiber.New(fiber.Config{AppName: "api-db-go-moderation-enabled-test"})
	app.Use(middlewares.Recover())
	app.Use(middlewares.Auth(testSecret))
	eh := handlers.NewEnabledHandler(music, greeter, logs, mocks.NewFakeModuleCache()).WithModeration(moderation)
	routers.RegisterModuleEnabled(app, eh)

	status, _, body := doModuleReq(t, app, "GET", "/bots/b1/guilds/g1/modules/enabled/", "Bearer "+testSecret, nil)
	if status != 200 {
		t.Fatalf("status = %d, want 200\nbody: %s", status, body)
	}
	var env struct {
		Data []string `json:"data"`
	}
	if err := json.Unmarshal(body, &env); err != nil {
		t.Fatalf("unmarshal: %v\nbody: %s", err, body)
	}
	found := false
	for _, k := range env.Data {
		if k == "moderation" {
			found = true
		}
	}
	if !found {
		t.Fatalf("enabled list %v should include moderation", env.Data)
	}
}

