// v2Raw devuelve un subdoc crudo tal cual lo dejó el schema v2: sin ninguno de
// los siete bloques del v3, con las tres reglas de automod de entonces y sin
// `count_as_warn`. Es el documento que hay HOY en producción.
func v2Raw() bson.M {
	return bson.M{
		"schema_version":       int32(2),
		"enabled":              true,
		"command_mode":         "slash",
		"track_native_actions": true,
		"commands": bson.M{
			"ban": bson.M{"enabled": false, "use_global": true},
		},
		"automod": bson.M{
			"mentions": bson.M{"enabled": true, "action": "delete_warn", "timeout_ms": 60000, "max_mentions": 4},
			"words":    bson.M{"enabled": false, "action": "delete", "timeout_ms": 300000},
			"invites":  bson.M{"enabled": false, "action": "delete", "timeout_ms": 300000},
		},
	}
}

// TestMigrateModerationRaw_V2DocGetsV3Defaults 🛡️ — el caso central: un
// documento v2 pasa por la migración y sale con los defaults NO-CERO del v3
// puestos (ventanas, umbrales, `timeout_ms`, protecciones activas) y la versión
// sellada a 3. Sin esto, un decode directo al struct dejaría todo a 0 y el
// anti-raid se activaría con umbral 0 y ventana 0.
func TestMigrateModerationRaw_V2DocGetsV3Defaults(t *testing.T) {
	m := MigrateModerationRaw(v2Raw())
	NormalizeModeration(&m) // todo call site empareja las dos

	if m.SchemaVersion != SchemaVersionModeration {
		t.Fatalf("schema_version = %d, want %d", m.SchemaVersion, SchemaVersionModeration)
	}

	// Lo que ya existía sobrevive intacto.
	if !m.Enabled || m.CommandMode != ModerationCommandModeSlash {
		t.Fatalf("la migración pisó campos del v2: enabled=%v command_mode=%q", m.Enabled, m.CommandMode)
	}
	if m.Commands["ban"].Enabled {
		t.Fatalf("commands.ban.enabled = true, want false (config del v2 pisada)")
	}
	if !m.Automod.Mentions.Enabled || m.Automod.Mentions.Action != AutomodActionDeleteWarn ||
		m.Automod.Mentions.TimeoutMs != 60000 || m.Automod.Mentions.MaxMentions != 4 {
		t.Fatalf("automod.mentions pisado por el default: %+v", m.Automod.Mentions)
	}

	// Los 11 comandos del v3 se siembran; los del v2 no se tocan.
	if len(m.Commands) != len(ModerationCommandNames) {
		t.Fatalf("commands tiene %d entradas, want %d", len(m.Commands), len(ModerationCommandNames))
	}
	for _, name := range []string{"limpiar", "lock", "unlock", "slowmode", "vcmute", "vcunmute", "vcexpulsar", "mover", "nota", "caso", "raid"} {
		c, ok := m.Commands[name]
		if !ok {
			t.Fatalf("comando del v3 %q sin sembrar", name)
		}
		if !c.Enabled || !c.UseGlobal || !c.DmEnabled || c.Aliases == nil {
			t.Fatalf("commands[%s] = %+v, want activo + hereda global + DM + aliases []", name, c)
		}
	}

	// Las seis reglas nuevas de automod, con sus parámetros NO-cero.
	if m.Automod.Spam.MaxMessages != 5 || m.Automod.Spam.WindowMs != 5000 || !m.Automod.Spam.PurgeBurst {
		t.Fatalf("automod.spam = %+v, want 5/5000/purge_burst", m.Automod.Spam)
	}
	if m.Automod.Duplicates.MaxRepeats != 3 || m.Automod.Duplicates.WindowMs != 30000 {
		t.Fatalf("automod.duplicates = %+v, want 3/30000", m.Automod.Duplicates)
	}
	if m.Automod.Caps.MinLength != 10 || m.Automod.Caps.MaxPercent != 70 {
		t.Fatalf("automod.caps = %+v, want 10/70", m.Automod.Caps)
	}
	if m.Automod.Emojis.MaxEmojis != 10 {
		t.Fatalf("automod.emojis.max_emojis = %d, want 10", m.Automod.Emojis.MaxEmojis)
	}
	for name, timeout := range map[string]int{
		"spam":        m.Automod.Spam.TimeoutMs,
		"duplicates":  m.Automod.Duplicates.TimeoutMs,
		"caps":        m.Automod.Caps.TimeoutMs,
		"links":       m.Automod.Links.TimeoutMs,
		"emojis":      m.Automod.Emojis.TimeoutMs,
		"attachments": m.Automod.Attachments.TimeoutMs,
	} {
		if timeout != AutomodDefaultTimeoutMs {
			t.Fatalf("automod.%s.timeout_ms = %d, want %d (el default no-cero se perdió)", name, timeout, AutomodDefaultTimeoutMs)
		}
	}

	// Los siete bloques nuevos, con sus defaults no-cero.
	if !m.Protection.RespectHierarchy || !m.Protection.ProtectAdmins || !m.Protection.ProtectBots {
		t.Fatalf("protection = %+v, want la red de seguridad activa", m.Protection)
	}
	if m.Escalation.WindowMs != 30*24*60*60*1000 || len(m.Escalation.CountTypes) != 1 {
		t.Fatalf("escalation = %+v, want ventana de 30 días y count_types [warn]", m.Escalation)
	}
	if m.Effects.PurgeOnBan.Policy != ModerationEffectAsk || m.Effects.PurgeOnBanSeconds != 86400 {
		t.Fatalf("effects = %+v, want purge_on_ban ask + 86400 s", m.Effects)
	}
	if m.Raid.JoinThreshold != 10 || m.Raid.JoinWindowMs != 10000 || m.Raid.DurationMs != 600000 {
		t.Fatalf("raid = %+v, want 10/10000/600000", m.Raid)
	}
	if m.Gate.Action != ModerationGateAlert || !m.Gate.ExemptBots {
		t.Fatalf("gate = %+v, want alert + exempt_bots", m.Gate)
	}
	if m.Antinuke.Punishment != ModerationNukePunishStripRoles || len(m.Antinuke.Limits) != len(ModerationNukeActionNames) {
		t.Fatalf("antinuke = %+v, want strip_roles y las 13 acciones sembradas", m.Antinuke)
	}
	for _, action := range ModerationNukeActionNames {
		lim := m.Antinuke.Limits[string(action)]
		if lim.WindowMs != 60000 || lim.Max <= 0 || lim.Punishment != ModerationNukePunishInherit {
			t.Fatalf("antinuke.limits[%s] = %+v, want ventana 60000 / tope > 0 / inherit", action, lim)
		}
	}
	if m.Lockdown.BypassRoles == nil || m.Lockdown.ServerChannels == nil {
		t.Fatalf("lockdown = %+v, want listas []", m.Lockdown)
	}
}

// TestMigrateModerationRaw_Idempotent 🛡️ — migrar dos veces da el mismo
// resultado: el segundo paso ya no encuentra nada ausente y no toca nada.
func TestMigrateModerationRaw_Idempotent(t *testing.T) {
	first := MigrateModerationRaw(v2Raw())
	NormalizeModeration(&first)

	// Se vuelve a serializar a crudo, tal cual lo persistiría el repo, y se
	// migra otra vez.
	b, err := bson.Marshal(first)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	var raw bson.M
	if err := bson.Unmarshal(b, &raw); err != nil {
		t.Fatalf("unmarshal: %v", err)
	}
	second := MigrateModerationRaw(raw)
	NormalizeModeration(&second)

	firstJSON, _ := json.Marshal(first)
	secondJSON, _ := json.Marshal(second)
	if string(firstJSON) != string(secondJSON) {
		t.Fatalf("la migración no es idempotente:\n1ª: %s\n2ª: %s", firstJSON, secondJSON)
	}
}

// TestMigrateModerationRaw_KeepsHandPickedZeroes 🛡️ — la ausencia se detecta
// por la CLAVE del crudo, no por el valor cero del struct: un umbral que
// alguien puso a 0 A PROPÓSITO desde la dashboard NO se pisa con el default.
func TestMigrateModerationRaw_KeepsHandPickedZeroes(t *testing.T) {
	raw := v2Raw()
	raw["escalation"] = bson.M{
		"enabled":             true,
		"window_ms":           int32(0), // "cuenta todo el historial", a propósito
		"count_types":         bson.A{"warn", "kick"},
		"count_automod":       false,
		"reset_after_trigger": false,
		"rules":               bson.A{bson.M{"threshold": int32(3), "action": "kick", "duration_ms": int32(0)}},
	}
	raw["raid"] = bson.M{
		"enabled":        true,
		"join_threshold": int32(0), // anti-raid deliberadamente sin umbral
		"join_window_ms": int32(0),
		"action":         "lockdown",
	}
	raw["automod"] = bson.M{
		"mentions": bson.M{"enabled": true, "action": "delete", "timeout_ms": int32(1000)},
		"spam":     bson.M{"enabled": true, "action": "delete", "timeout_ms": int32(0), "max_messages": int32(0), "window_ms": int32(0)},
	}

	m := MigrateModerationRaw(raw)
	NormalizeModeration(&m)

	if m.Escalation.WindowMs != 0 || !m.Escalation.Enabled || m.Escalation.CountAutomod || m.Escalation.ResetAfterTrigger {
		t.Fatalf("escalation puesto a mano pisado por el default: %+v", m.Escalation)
	}
	if len(m.Escalation.Rules) != 1 || m.Escalation.Rules[0].Threshold != 3 {
		t.Fatalf("escalation.rules pisado: %+v", m.Escalation.Rules)
	}
	if m.Raid.JoinThreshold != 0 || m.Raid.JoinWindowMs != 0 || m.Raid.Action != ModerationRaidLockdown {
		t.Fatalf("raid puesto a mano pisado por el default: %+v", m.Raid)
	}
	if m.Automod.Spam.MaxMessages != 0 || m.Automod.Spam.WindowMs != 0 || m.Automod.Spam.TimeoutMs != 0 {
		t.Fatalf("automod.spam puesto a mano pisado por el default: %+v", m.Automod.Spam)
	}
	// Y las reglas que SÍ faltaban en ese `automod` recortado sí reciben default.
	if m.Automod.Words.TimeoutMs != AutomodDefaultTimeoutMs || m.Automod.Caps.MinLength != 10 {
		t.Fatalf("las reglas ausentes deberían llevar default: words=%+v caps=%+v", m.Automod.Words, m.Automod.Caps)
	}
}

// TestMigrateModerationRaw_NestedBsonD 🛡️ — la forma REAL que llega de Mongo:
// el driver v2 decodifica todo sub-documento anidado dentro de un `bson.M` como
// `bson.D`. Si la detección de bloques no lo contempla, cada lectura creería que
// `automod`/`antinuke` no existen y los pisaría con los defaults, borrando la
// configuración del servidor en cada GET.
func TestMigrateModerationRaw_NestedBsonD(t *testing.T) {
	// Se construye igual que lo haría el repo: documento → BSON → bson.M.
	doc := bson.M{"module_moderation": v2Raw()}
	b, err := bson.Marshal(doc)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	var out struct {
		ModuleModeration bson.M `bson:"module_moderation"`
	}
	if err := bson.Unmarshal(b, &out); err != nil {
		t.Fatalf("unmarshal: %v", err)
	}
	if _, isD := out.ModuleModeration["automod"].(bson.D); !isD {
		t.Fatalf("precondición: se esperaba un bson.D anidado, got %T", out.ModuleModeration["automod"])
	}

	m := MigrateModerationRaw(out.ModuleModeration)
	NormalizeModeration(&m)

	if !m.Automod.Mentions.Enabled || m.Automod.Mentions.Action != AutomodActionDeleteWarn || m.Automod.Mentions.TimeoutMs != 60000 {
		t.Fatalf("automod.mentions se pisó con el default en la forma bson.D: %+v", m.Automod.Mentions)
	}
	// Y las reglas del v3, que sí faltaban, reciben su default no-cero.
	if m.Automod.Caps.MinLength != 10 || m.Automod.Spam.WindowMs != 5000 {
		t.Fatalf("las reglas del v3 no recibieron default: caps=%+v spam=%+v", m.Automod.Caps, m.Automod.Spam)
	}
}

