// TestModerationRawSchemaVersion 🛡️ — tolera las formas int/int32/int64/float64
// que producen los decoders de Mongo/JSON; ausente → 0.
func TestModerationRawSchemaVersion(t *testing.T) {
	cases := []struct {
		val  any
		want int
	}{
		{int(2), 2}, {int32(2), 2}, {int64(2), 2}, {float64(2), 2}, {nil, 0}, {"2", 0},
	}
	for _, c := range cases {
		raw := bson.M{}
		if c.val != nil {
			raw["schema_version"] = c.val
		}
		if got := ModerationRawSchemaVersion(raw); got != c.want {
			t.Fatalf("ModerationRawSchemaVersion(%v) = %d, want %d", c.val, got, c.want)
		}
	}
}

// TestNormalizeModeration_V3NilCollections 🛡️ — un módulo del v3 decodificado
// con las colecciones nuevas a nil sale con `[]` / `{}`, nunca `null`, y los
// nullables nuevos (`raid.alert_*`, `gate.alert_channel_id`, `antinuke.alert_*`)
// se quedan en `null`.
func TestNormalizeModeration_V3NilCollections(t *testing.T) {
	m := ModuleModeration{SchemaVersion: SchemaVersionModeration}
	NormalizeModeration(&m)

	for name, s := range map[string][]string{
		"protection.immune_roles":            m.Protection.ImmuneRoles,
		"protection.immune_users":            m.Protection.ImmuneUsers,
		"protection.hierarchy_bypass_roles":  m.Protection.HierarchyBypassRoles,
		"raid.lockdown_channels":             m.Raid.LockdownChannels,
		"gate.blocked_name_patterns":         m.Gate.BlockedNamePatterns,
		"antinuke.trusted_users":             m.Antinuke.TrustedUsers,
		"antinuke.trusted_roles":             m.Antinuke.TrustedRoles,
		"lockdown.bypass_roles":              m.Lockdown.BypassRoles,
		"lockdown.server_channels":           m.Lockdown.ServerChannels,
		"automod.links.allowed_domains":      m.Automod.Links.AllowedDomains,
		"automod.links.blocked_domains":      m.Automod.Links.BlockedDomains,
		"automod.attachments.blocked_ext":    m.Automod.Attachments.BlockedExtensions,
		"automod.spam.exempt_roles":          m.Automod.Spam.ExemptRoles,
		"automod.duplicates.exempt_channels": m.Automod.Duplicates.ExemptChannels,
		"automod.caps.exempt_roles":          m.Automod.Caps.ExemptRoles,
		"automod.emojis.exempt_channels":     m.Automod.Emojis.ExemptChannels,
	} {
		if s == nil {
			t.Fatalf("normalize dejó nil en %s", name)
		}
	}
	if m.Escalation.CountTypes == nil || m.Escalation.Rules == nil {
		t.Fatalf("normalize dejó nil en escalation: %+v", m.Escalation)
	}
	if m.Antinuke.Limits == nil {
		t.Fatalf("normalize dejó nil en antinuke.limits")
	}

	b, err := json.Marshal(m)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	js := string(b)
	for _, bad := range []string{
		`"immune_roles":null`, `"count_types":null`, `"rules":null`, `"limits":null`,
		`"lockdown_channels":null`, `"blocked_name_patterns":null`,
		`"allowed_domains":null`, `"blocked_extensions":null`, `"bypass_roles":null`,
	} {
		if strings.Contains(js, bad) {
			t.Fatalf("el JSON normalizado no debe contener %s:\n%s", bad, js)
		}
	}
	// Los nullables nuevos SÍ se quedan en null: es como se codifica "usa el
	// canal de mod-log" / "sin mención".
	for _, want := range []string{`"alert_channel_id":null`, `"alert_role_id":null`} {
		if !strings.Contains(js, want) {
			t.Fatalf("falta %s en el JSON normalizado:\n%s", want, js)
		}
	}
}

// TestNormalizeModeration_FlowsBackfillsCollections 🛡️ — `Flows` decodificado a
// nil sale como `[]` no-nulo (nunca `null`), y las colecciones internas de
// cada flujo (`Setup`/`Conditions`/`Steps`) que hayan decodificado a nil
// también se rellenan. `Branches` es la EXCEPCIÓN: nil se queda nil (ver el
// siguiente test).
func TestNormalizeModeration_FlowsBackfillsCollections(t *testing.T) {
	m := &ModuleModeration{SchemaVersion: SchemaVersionModeration}
	NormalizeModeration(m)
	if m.Flows == nil || len(m.Flows) != 0 {
		t.Fatalf("Flows = %+v, want [] no-nulo", m.Flows)
	}

	m2 := &ModuleModeration{
		SchemaVersion: SchemaVersionModeration,
		Flows:         []ModerationFlow{{ID: "f1", Trigger: ModerationFlowTrigger{Type: "message_sent"}}},
	}
	NormalizeModeration(m2)
	f := m2.Flows[0]
	if f.Setup == nil || f.Conditions == nil || f.Steps == nil {
		t.Fatalf("Setup/Conditions/Steps = %+v/%+v/%+v, se esperaban listas vacías no-nulas", f.Setup, f.Conditions, f.Steps)
	}
	if f.Trigger.Params == nil {
		t.Fatal("Trigger.Params = nil, se esperaba un mapa vacío no-nulo")
	}
	if f.Scope.Channels.IDs == nil || f.Scope.Categories.IDs == nil || f.Scope.Roles.IDs == nil {
		t.Fatalf("scope access-list ids = %+v, se esperaban listas vacías no-nulas", f.Scope)
	}

	b, err := json.Marshal(m2)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	js := string(b)
	for _, want := range []string{`"setup":[]`, `"conditions":[]`, `"steps":[]`, `"params":{}`} {
		if !strings.Contains(js, want) {
			t.Fatalf("el JSON normalizado no contiene %s:\n%s", want, js)
		}
	}
}

// TestNormalizeModeration_FlowsBranchesOmittedWhenNil 🛡️ — `branches` ausente
// (nil) es un estado LEGÍTIMO («sin ramas»): NormalizeModeration no lo fuerza
// a `[]`, y el JSON omite la clave por completo — mismo criterio que
// `Automation.Branches` (§1 del contrato: "Ausente o vacío = sin ramas").
func TestNormalizeModeration_FlowsBranchesOmittedWhenNil(t *testing.T) {
	m := &ModuleModeration{
		SchemaVersion: SchemaVersionModeration,
		Flows:         []ModerationFlow{{ID: "f1"}},
	}
	NormalizeModeration(m)
	if m.Flows[0].Branches != nil {
		t.Fatalf("Branches = %+v, want nil (normalize no debe forzarlo a [])", m.Flows[0].Branches)
	}
	b, err := json.Marshal(m)
	if err != nil {
		t.Fatalf("marshal: %v", err)
	}
	if strings.Contains(string(b), `"branches"`) {
		t.Fatalf("el JSON no debe contener la clave \"branches\" cuando Branches es nil:\n%s", b)
	}
}

// TestNormalizeModeration_FlowsFlattensBSONParams 🛡️ — el caso que motiva todo
// el aplanado (mismo que TestNormalizeAutomation_FlattensBSONDocuments): un
// subdocumento decodificado de Mongo llega como `bson.D`/`bson.A`. Sin
// aplanarlo, `json.Marshal` lo escribe como `[{"Key":…,"Value":…}]` — corrupto
// para el módulo y para el merge del PATCH, que también pasa por JSON. Cubre
// los CUATRO sitios donde vive un `params` libre: el trigger, una condición
// raíz, un paso de `setup` y un paso/condición dentro de una rama.
func TestNormalizeModeration_FlowsFlattensBSONParams(t *testing.T) {
	m := &ModuleModeration{
		SchemaVersion: SchemaVersionModeration,
		Flows: []ModerationFlow{{
			ID: "f1",
			Trigger: ModerationFlowTrigger{
				Type:   "message_sent",
				Params: map[string]any{"nested": bson.D{{Key: "deep", Value: bson.D{{Key: "n", Value: 1}}}}},
			},
			Setup: []ModerationFlowStep{{
				ID: "s1", Type: "set_variable",
				Params: map[string]any{"embed": bson.D{{Key: "title", Value: "hola"}}},
			}},
			Conditions: []ModerationFlowCondition{{
				ID: "c1", Type: "message_contains",
				Params: map[string]any{"values": bson.A{"a", "b"}},
			}},
			Steps: []ModerationFlowStep{{
				ID: "st1", Type: "warn_member",
				Params: map[string]any{"opts": bson.D{{Key: "notify_dm", Value: true}}},
			}},
			Branches: []ModerationFlowBranch{{
				ID: "b1",
				Conditions: []ModerationFlowCondition{{
					ID: "bc1", Type: "chance",
					Params: map[string]any{"cfg": bson.D{{Key: "percent", Value: 50}}},
				}},
				Steps: []ModerationFlowStep{{
					ID: "bs1", Type: "kick_member",
					Params: map[string]any{"tags": bson.A{"x"}},
				}},
			}},
		}},
	}
	NormalizeModeration(m)

	assertFlatObject := func(label string, params map[string]any) {
		t.Helper()
		raw, err := json.Marshal(params)
		if err != nil {
			t.Fatalf("%s: json.Marshal: %v", label, err)
		}
		if strings.Contains(string(raw), `"Key"`) || strings.Contains(string(raw), `"Value"`) {
			t.Fatalf("%s salió sin aplanar (todavía bson.D): %s", label, raw)
		}
	}

	f := m.Flows[0]
	assertFlatObject("trigger.params", f.Trigger.Params)
	assertFlatObject("setup[0].params", f.Setup[0].Params)
	assertFlatObject("conditions[0].params", f.Conditions[0].Params)
	assertFlatObject("steps[0].params", f.Steps[0].Params)
	assertFlatObject("branches[0].conditions[0].params", f.Branches[0].Conditions[0].Params)
	assertFlatObject("branches[0].steps[0].params", f.Branches[0].Steps[0].Params)

	// El anidado profundo (trigger.params.nested.deep) también debe quedar
	// como objeto JSON normal, no sólo el primer nivel.
	nested, ok := f.Trigger.Params["nested"].(map[string]any)
	if !ok {
		t.Fatalf("trigger.params.nested salió como %T, se esperaba un objeto JSON", f.Trigger.Params["nested"])
	}
	if _, ok := nested["deep"].(map[string]any); !ok {
		t.Fatalf("trigger.params.nested.deep salió como %T, el aplanado no es recursivo", nested["deep"])
	}
}

func TestNormalizeModeration_FlowsIdempotent(t *testing.T) {
	m := &ModuleModeration{
		SchemaVersion: SchemaVersionModeration,
		Flows: []ModerationFlow{{
			ID:      "f1",
			Trigger: ModerationFlowTrigger{Type: "message_sent", Params: map[string]any{"n": bson.D{{Key: "k", Value: "v"}}}},
		}},
	}
	NormalizeModeration(m)
	first, _ := json.Marshal(m)
	NormalizeModeration(m)
	second, _ := json.Marshal(m)
	if string(first) != string(second) {
		t.Fatalf("no es idempotente:\n1: %s\n2: %s", first, second)
	}
}

