package validations

import (
	"kena.bot/api-db-go/internal/domain/dbguild"
	apierrors "kena.bot/api-db-go/internal/domain/errors"
)

// UpdateModuleModerationBody mirrors the Node `updateModuleModerationSchema`
// (a `.strict()` object of `.optional()` fields). The handler decodes this
// with `DisallowUnknownFields` (matching the zod `.strict()` — unknown
// keys top-level OR nested are a 400) and then re-decodes the SAME raw
// body as `map[string]any`, which the repository merges into the existing
// subdoc via `mongo.MergeDeepJSON` by KEY PRESENCE: a key absent in the
// body is left alone; an explicit `false`/`0`/`""`/`null` is applied and
// overrides the stored value; nested objects (`commands_global`, `mute`,
// `automod`) recurse; the `commands` map merges per-key; slices replace
// wholesale.
//
// UNLIKE the READ schema, the PATCH schema exposes NO `schema_version`
// / `updated_at` — those are stamped by the repo on every write. Every
// other READ field IS patchable here (the READ and PATCH catalogs
// otherwise match).
//
// `log_channel_id` is the only TOP-LEVEL nullable string (`string |
// null`). Because merge is presence-based, sending `null` clears it to
// null and omitting the key preserves the stored value — exactly like
// Node's `mergeDeep`, with no special-case handling in this struct. The
// nested nullables (`mute.role_id`, each command's `dm_embed.color`)
// ride inside their parent structs and are merged recursively.
//
// REMAINING CAVEATS (inherited from the old MergeDeep mold, NOT from
// presence-based behaviour):
//   - Go's json decoder does NOT enforce zod's REQUIRED-ness inside a
//     present nested object (Node's `commandAccessUpdateSchema` /
//     `automod*` rule schemas are `.strict()` with every field
//     required), so a partial nested object that Node would 400 is
//     accepted here and the missing leaves stay zero — the same
//     non-strict-required behaviour every Go module body has.
//   - The zod value constraints (`dm_embed.content` max 4000, the numeric
//     floors like `raid.join_threshold.min(2)`) are NOT enforced here. Same
//     as every other Go module body — `0` already means "off" everywhere the
//     bot reads these, so a missing floor degrades to the default behaviour,
//     not to something the bot can't execute.
//   - The zod ENUM constraints (`command_mode`, `mute.mode`, every automod
//     rule's `action`) ARE enforced, but NOT here — the handler's
//     `ValidateModerationPatchEnums` checks them against the raw patch map
//     after this decode, because the nested domain structs use plain values
//     for their leaves and can't tell "absent" from `""` the way this
//     pointer-typed struct can for its top-level fields.
//
// Cada clave de nivel superior del schema DEBE tener su puntero aquí: si falta
// una, el PATCH de la dashboard se come un 400 "unknown field" (el handler
// decodifica con `DisallowUnknownFields`). Por eso los siete bloques del v3
// (`protection`, `escalation`, `effects`, `raid`, `gate`, `antinuke`,
// `lockdown`) están listados igual que `automod` — y `flows` (v4) igual.
//
// `Flows` reutiliza `dbguild.ModerationFlow` TAL CUAL (mismo precedente que
// `Creators *[]dbguild.TempvoiceCreator` / `TicketTypes *[]dbguild.TicketsType`
// / `TicketTypes *[]dbguild.ModmailTicketType`), no un tipo "Body" duplicado:
// el struct de dominio YA tiene exactamente la forma que la dashboard envía
// (§5.3 del contrato de flujos: el PATCH sustituye el array ENTERO, así que
// cada flujo llega completo, con `id`/`created_at`/`updated_at` incluidos).
// Los `params` de trigger/condiciones/pasos siguen siendo `map[string]any`
// libre — su forma la valida el catálogo compartido, no Go — así que
// `DisallowUnknownFields` no los toca; sí rechaza cualquier clave desconocida
// a nivel de `ModerationFlow`/`ModerationFlowScope`/etc., que es justo lo que
// se quiere.
type UpdateModuleModerationBody struct {
	Enabled            *bool                                 `json:"enabled,omitempty"`
	CommandMode        *dbguild.ModerationCommandMode        `json:"command_mode,omitempty"`
	CommandsGlobal     *dbguild.ModerationCommandAccess      `json:"commands_global,omitempty"`
	Commands           *map[string]dbguild.ModerationCommand `json:"commands,omitempty"`
	Mute               *dbguild.ModerationMute               `json:"mute,omitempty"`
	LogChannelID       *string                               `json:"log_channel_id,omitempty"`
	TrackNativeActions *bool                                 `json:"track_native_actions,omitempty"`
	Automod            *dbguild.ModerationAutomod            `json:"automod,omitempty"`
	Protection         *dbguild.ModerationProtection         `json:"protection,omitempty"`
	Escalation         *dbguild.ModerationEscalation         `json:"escalation,omitempty"`
	Effects            *dbguild.ModerationEffects            `json:"effects,omitempty"`
	Raid               *dbguild.ModerationRaid               `json:"raid,omitempty"`
	Gate               *dbguild.ModerationGate               `json:"gate,omitempty"`
	Antinuke           *dbguild.ModerationAntinuke           `json:"antinuke,omitempty"`
	Lockdown           *dbguild.ModerationLockdown           `json:"lockdown,omitempty"`
	Flows              *[]dbguild.ModerationFlow             `json:"flows,omitempty"`
}

// automodRuleKeys son las nueve claves de regla de AutoMod, en el MISMO orden
// que `automodSchema` / `ModerationAutomod` y que `AUTOMOD_RULES` en
// moderation-schema.ts.
var automodRuleKeys = []string{
	"mentions", "words", "invites", "spam", "duplicates", "caps", "links", "emojis", "attachments",
}

const (
	moderationCommandModeMsg = `Invalid option: expected one of "slash"|"prefix"|"both"`
	moderationMuteModeMsg    = `Invalid option: expected one of "auto"|"timeout"|"role"`
	automodActionMsg         = `Invalid option: expected one of "delete"|"delete_warn"|"delete_timeout"|"delete_kick"|"delete_ban"`
)

// ValidateModerationPatchEnums rechaza un PATCH de moderación cuyo body crudo
// pone una hoja de enum cerrado a un valor fuera de su conjunto conocido —
// INCLUIDA la cadena vacía, que decodifica sin problema (Go tipa cada enum de
// dominio como un string plano) pero que el runtime del bot sólo compara con
// `===` contra los miembros conocidos: `command_mode` cae en la rama más
// permisiva (`both`), `mute.mode` cae en `auto`, y la `action` de cualquier
// regla de automod cae en `delete` — una config que en el dashboard SE VE
// guardada pero que el bot reinterpreta en silencio. Ver
// AUDITORIA-fallos-silenciosos-2026-08-11.md (moderation-module), hallazgos
// 10/13/14: el volcado de un guild real citado ahí trae exactamente estos
// tres campos vacíos.
//
// Corre sobre el mapa CRUDO del patch, no sobre el struct tipado: una clave
// ausente tiene que quedar intacta para este check (un
// `{"mute":{"role_id":"123"}}` parcial omite `mode` a propósito —
// `MergeDeepJSON` deja el valor guardado tal cual — y el struct tipado no
// puede distinguir eso de un `""` explícito, porque los structs de dominio
// anidados usan valores planos, no punteros, para sus hojas).
//
// Deliberadamente ESTRECHO: esto NO replica los pisos numéricos del zod de
// dashboard (`raid.join_threshold.min(2)`, `escalation.rules[].threshold.min(1)`,
// `antinuke.limits[].max.min(1)`, …) — esos describen un valor recomendado,
// no uno imposible: `0` ya se trata explícitamente como "detección apagada"
// en todos los sitios que audita el informe. Sólo un valor fuera de un enum
// cerrado es genuinamente imposible de ejecutar para el bot.
func ValidateModerationPatchEnums(patch map[string]any) *apierrors.CustomError {
	if v, ok := patchStringLeaf(patch, "command_mode"); ok && !dbguild.ModerationCommandMode(v).Valid() {
		return zodItemError(moderationCommandModeMsg, "command_mode")
	}
	if v, ok := patchStringLeaf(patch, "mute", "mode"); ok && !dbguild.ModerationMuteMode(v).Valid() {
		return zodItemError(moderationMuteModeMsg, "mute.mode")
	}
	for _, rule := range automodRuleKeys {
		if v, ok := patchStringLeaf(patch, "automod", rule, "action"); ok && !dbguild.AutomodAction(v).Valid() {
			return zodItemError(automodActionMsg, "automod."+rule+".action")
		}
	}
	return nil
}

// patchStringLeaf camina un mapa crudo de patch siguiendo `path` y devuelve
// el string del final más si estaba presente. Ausente en cualquier nivel
// (clave que falta, o un valor que no es un objeto donde se esperaba uno)
// reporta `!ok` — "no presente", nunca un error: el merge por presencia
// exige que la llamante trate eso igual que "sin tocar".
func patchStringLeaf(patch map[string]any, path ...string) (string, bool) {
	cur := any(patch)
	for i, key := range path {
		m, ok := cur.(map[string]any)
		if !ok {
			return "", false
		}
		v, present := m[key]
		if !present {
			return "", false
		}
		if i == len(path)-1 {
			s, ok := v.(string)
			return s, ok
		}
		cur = v
	}
	return "", false
}

